function grayRGBA(rgba){const raw=new Uint8Array(rgba.length/4);for(let i=0;i<raw.length;i++){const alpha=rgba[4*i+3]/255;const r=rgba[4*i]*alpha+255*(1-alpha),g=rgba[4*i+1]*alpha+255*(1-alpha),b=rgba[4*i+2]*alpha+255*(1-alpha);raw[i]=Math.round(.299*r+.587*g+.114*b)}return raw}
function fitRectangle(w,h,fit){const scale=fit==='cover'?Math.max(128/w,128/h):Math.min(128/w,128/h);return {x:(128-w*scale)/2,y:(128-h*scale)/2,width:w*scale,height:h*scale}}
if(typeof module!=='undefined')module.exports={grayRGBA,fitRectangle};
if(typeof document!=='undefined'){
const $=id=>document.getElementById(id);let state=null,asset=null,busy=false,loading=false,rendered=null,assetListSignature=null,previewAsset=null;
const pretty=o=>JSON.stringify(o,null,2);function error(e){$('error').textContent=e.message||String(e);$('error').style.display='block'}
function controls(){const p=state?.pilot,s=p?.state;const sealed=!!state?.prepared||state?.stage==='BLOCKED_SETUP';$('upload').disabled=busy||sealed||!$('file').files.length;$('file').disabled=busy||sealed;$('fit').disabled=busy||sealed;$('assets').disabled=busy||sealed;$('seed').disabled=busy||sealed;$('prepare').disabled=busy||!state?.linked||!asset||sealed;$('send').disabled=busy||s!=='READY';$('stop').disabled=busy||!['READY','RUNNING','STOPPING'].includes(s)}
async function post(path,body){let r=await fetch('/api/images/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Lab-Token':state.csrf},body:JSON.stringify(body)});let v=await r.json();if(!r.ok)throw Error(v.error||'请求失败');return v}
function showAsset(meta){asset=meta;$('assetInfo').textContent=meta.filename+' · 128×128 灰度 · '+meta.bytes+' 字节\nSHA256 '+meta.source_sha256;if(previewAsset!==meta.asset_id){previewAsset=meta.asset_id;$('preview').src='/api/images/asset/'+meta.asset_id+'/source.png'}$('preview').hidden=false;$('assets').value=meta.asset_id;controls()}
function showResults(){if(state?.artifacts?.status!=='READY')return;const report=state.artifacts.report,method=$('method').value,key=report.session+'|'+method;
 if(key!==rendered){rendered=key;const base='/api/images/artifact/';for(const [id,file] of Object.entries({sourceResult:'evaluation_reference.png',bReceived:'B_received.png',stmReceived:'STM_received.png',repaired:method+'/data.png',missing:'B_missing.png',uncertain:method+'/uncertain.png'}))$(id).src=base+file}
 $('results').hidden=false;$('metrics').textContent=pretty({complete_image_capture:report.complete_image_capture,completed_records:report.completed_records,missing_pixels:report.missing_pixels,baselines:report.baselines,selected_method:method,repair:report.methods[method],source_pixels_used_by_repair:report.repair_input_source_pixels})}
async function refresh(){if(loading)return;loading=true;try{const r=await fetch('/api/images/state');if(!r.ok)throw Error('图片服务状态读取失败');state=await r.json();
 $('connection').textContent=state.linked?'已连接新会话整图执行器':'未连接整图执行器：可以上传预览，发送按钮禁用';
 const selected=asset?.asset_id||$('assets').value,signature=JSON.stringify(state.assets.map(a=>[a.asset_id,a.filename]));if(signature!==assetListSignature){assetListSignature=signature;$('assets').replaceChildren(new Option('请选择',''));for(const meta of state.assets)$('assets').add(new Option(meta.filename+' · '+meta.source_sha256.slice(0,12),meta.asset_id));$('assets').value=selected}
 if(state.prepared){showAsset(state.prepared.metadata);$('seed').value=state.prepared.seed;$('plan').textContent=pretty({asset_id:state.prepared.asset_id,seed:state.prepared.seed,source_sha256:state.prepared.metadata.source_sha256,limit:65,plan_sha256:state.prepared.plan_sha256,planned_points:state.pilot.plan.planned_points})}
 if(state.pilot){const p=state.pilot;$('progress').textContent=p.state+' · 已尝试 '+p.attempts+'/65 · 已核验并退役 '+p.completed_records+'/65'+(p.stop_requested?' · 已请求停止剩余块':'');if(p.error)$('progress').textContent+=' · '+p.error;
 $('artifactState').textContent=state.artifacts.status+(state.artifacts.error?' · '+state.artifacts.error:'');$('download').hidden=!state.worker_finished||['READY','RUNNING','STOPPING'].includes(p.state);showResults()}
 if(state.error)error(Error(state.error));
 }catch(e){error(e)}finally{loading=false;controls()}}
function b64(raw){let s='';for(let i=0;i<raw.length;i+=32768)s+=String.fromCharCode(...raw.subarray(i,i+32768));return btoa(s)}
async function upload(){if(busy)return;busy=true;controls();let url=null;try{const file=$('file').files[0];if(!file||file.size>8*1024*1024)throw Error('请选择不超过8 MiB的图片');url=URL.createObjectURL(file);const image=new Image();image.src=url;await image.decode();const w=image.naturalWidth,h=image.naturalHeight;if(w>8192||h>8192||w*h>32000000)throw Error('图片像素尺寸过大');
 const canvas=document.createElement('canvas');canvas.width=canvas.height=128;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.fillStyle='white';ctx.fillRect(0,0,128,128);const rect=fitRectangle(w,h,$('fit').value);ctx.drawImage(image,rect.x,rect.y,rect.width,rect.height);const raw=grayRGBA(ctx.getImageData(0,0,128,128).data);
 const meta=await post('upload',{filename:file.name,original_base64:b64(new Uint8Array(await file.arrayBuffer())),raw_base64:b64(raw),transform:{width:128,height:128,original_width:w,original_height:h,fit:$('fit').value,conversion:'BROWSER_CANVAS_BT601_ROUND'}});showAsset(meta);$('error').style.display='none';await refresh();
 }catch(e){error(e)}finally{if(url)URL.revokeObjectURL(url);busy=false;controls()}}
function operationKey(action){const scope='pynq_image_'+state.pilot.session+'_'+state.pilot.plan_sha256+'_'+action;let key=localStorage.getItem(scope);if(!key){key=crypto.randomUUID();localStorage.setItem(scope,key)}return key}
async function command(action){if(busy)return;busy=true;controls();try{if(action==='prepare'){const seed=Number($('seed').value);if(!Number.isInteger(seed)||seed<0||seed>4294967295)throw Error('种子须为0～4294967295整数');await post('prepare',{asset_id:asset.asset_id,seed})}else await post(action,{plan_sha256:state.pilot.plan_sha256,idempotency_key:operationKey(action)});$('error').style.display='none';await refresh()}catch(e){error(e)}finally{busy=false;controls()}}
 $('file').onchange=controls;$('assets').onchange=()=>{const meta=state.assets.find(a=>a.asset_id===$('assets').value);if(meta)showAsset(meta)};$('upload').onclick=upload;$('prepare').onclick=()=>command('prepare');$('send').onclick=()=>command('start');$('stop').onclick=()=>command('stop');$('method').onchange=showResults;refresh();setInterval(refresh,1500);
}
